#!/usr/bin/env python3
"""AC-06.1, AC-03.2, AC-04.1a, AC-26.1: path allowlist / default deny on the live edge (02-TRD s6.3).

The allowed api paths and the AC-26.1 exemption list are read from infra/edge/public-routes.yaml (generated by
infra/ci/gen-routes.sh), never retyped here. "404 from nginx" = status 404 with nginx's own error page.
Env: LIMS_ORIGIN_STAFF_WEB, LIMS_ORIGIN_PORTAL, LIMS_ORIGIN_API (required), LIMS_ORIGIN_PARTNER (optional),
LIMS_EDGE_ADDR, LIMS_TLS_CA or LIMS_TLS_INSECURE=1, LIMS_ROUTES_YAML (default: the committed file).
Exit 2 when no target is configured.
"""
import http.client
import os
import re
import socket
import ssl
import sys
from pathlib import Path

RESERVED = ["/v1/", "/rest/v1/", "/graphql/v1", "/functions/v1/", "/auth/v1/", "/storage/v1/", "/realtime/v1/", "/pg/",
            "/api/mcp", "/mcp"]
API_DENY = ["/", "/pg/", "/api/mcp", "/mcp", "/rest/v1/", "/graphql/v1", "/functions/v1/", "/auth/v1/", "/storage/v1/",
            "/realtime/v1/", "/v1/identity/auth/login", "/v1/identity/auth/session/resolve", "/v1/identity/users",
            "/v1/core/health/live", "/v1/core/health/ready", "/v1/platform/tenants", "/v1/reporting/verifications"]
STORAGE = ["/storage/v1/object/public/x", "/storage/v1/object/sign/x", "/storage/v1/"]
APP_PATHS = ["/", "/auth/login"]


def origins():
    o = {k: os.environ.get("LIMS_ORIGIN_" + k.upper(), "") for k in ("staff_web", "portal", "api", "partner")}
    if not all(o[k] for k in ("staff_web", "portal", "api")):
        sys.stderr.write("routes.py: set LIMS_ORIGIN_STAFF_WEB, LIMS_ORIGIN_PORTAL, LIMS_ORIGIN_API\n")
        sys.exit(2)
    return {k: v for k, v in o.items() if v}


def tls_ctx():
    if os.environ.get("LIMS_TLS_INSECURE") == "1":
        c = ssl.create_default_context()
        c.check_hostname, c.verify_mode = False, ssl.CERT_NONE
        return c
    return ssl.create_default_context(cafile=os.environ.get("LIMS_TLS_CA") or None)


def req(host, method, path):
    ctx = tls_ctx()
    c = http.client.HTTPSConnection(host, 443, context=ctx, timeout=15)
    c.sock = ctx.wrap_socket(socket.create_connection((os.environ.get("LIMS_EDGE_ADDR") or host, 443), 15), server_hostname=host)
    c.request(method, path, headers={"Host": host})
    r = c.getresponse()
    body = r.read()
    c.close()
    return r.status, body


def nginx_404(status, body):
    return status == 404 and b"<center>nginx</center>" in body


def sample(path):
    return re.sub(r"\{[^}]*\}", "x", path)


def main():
    o = origins()
    import yaml  # after the target check: the fail-closed path needs no third-party module
    routes = yaml.safe_load(Path(os.environ.get("LIMS_ROUTES_YAML") or
                                 Path(__file__).resolve().parents[2] / "edge" / "public-routes.yaml").read_text())["routes"]
    fails = []

    def expect_deny(host, path):
        s, b = req(host, "GET", path)
        if not nginx_404(s, b):
            fails.append("%s %s: %s, want 404 from nginx" % (host, path, s))

    for name, host in o.items():
        for p in STORAGE:  # AC-03.2 on every public host
            expect_deny(host, p)
        if name == "api":
            continue
        for p in RESERVED:  # AC-06.1 BFF origins
            expect_deny(host, p)
            expect_deny(host, p + "x" if p.endswith("/") else p + "/x")
        for p in APP_PATHS:
            s, b = req(host, "GET", p)
            if nginx_404(s, b):
                fails.append("%s %s: refused by nginx, the app owns it" % (host, p))

    api = o["api"]
    allowed = [(r["match"], sample(r["path"])) for r in routes]

    def is_allowed(u):
        return any((m == "exact" and u == p) or (m != "exact" and u.startswith(p)) for m, p in allowed)

    for p in API_DENY:  # AC-06.1, AC-04.1a
        if not is_allowed(p):
            expect_deny(api, p)
    exempt = {p for _, p in allowed if p.startswith("/v1/identity/auth/")}  # AC-26.1 list comes from the YAML
    for p in ("/v1/identity/auth/login", "/v1/identity/auth/mfa/verify", "/v1/identity/auth/patient/session"):
        if p not in exempt:
            expect_deny(api, p)
    for m, p in allowed:  # every listed route reaches the API (whatever the app answers)
        u = p if m == "exact" or not p.endswith("/") else p + "x"
        method = "GET" if "GET" in next(r["methods"] for r in routes if sample(r["path"]) == p) else "POST"
        s, b = req(api, method, u)
        if nginx_404(s, b):
            fails.append("%s %s %s: listed in public-routes.yaml but refused by nginx" % (api, method, u))
    for f in fails:
        print("FAIL " + f)
    print("routes: %d failure(s)" % len(fails))
    return 1 if fails else 0


if __name__ == "__main__":
    sys.exit(main())
